document.querySelectorAll('[data-lab="BM04-I1"]').forEach(root=>{const zh=root.dataset.lang==='zh',get=s=>root.querySelector('[data-field="'+s+'"]'),pEl=get('pressure'),hEl=get('half');function update(){const p=Number(pEl.value),half=Number(hEl.value),mb=x=>x/(2.8+x),hb=x=>{const r=x/half;return Math.pow(r,2.8)/(1+Math.pow(r,2.8));},X=x=>75+x*3.9,Y=v=>320-v*245;get('pressureValue').textContent=p;get('halfValue').textContent=half;let grid='';[0,25,50,75,100].forEach(v=>{grid+='<path d="M75 '+Y(v/100)+' H543" stroke="#d9dfdc"/><text x="62" y="'+(Y(v/100)+7)+'" text-anchor="end" font-size="20">'+v+'</text>';});[0,40,80,120].forEach(v=>{grid+='<text x="'+X(v)+'" y="350" text-anchor="middle" font-size="20">'+v+'</text>';});const curve=f=>Array.from({length:121},(_,x)=>X(x)+','+Y(f(x))).join(' ');get('plot').innerHTML='<rect width="600" height="420" rx="16" fill="#f5f6ee"/><g fill="#153b43" font-family="system-ui,sans-serif">'+grid+'<path d="M75 65 V320 H543" stroke="#153b43" fill="none"/><polyline points="'+curve(mb)+'" fill="none" stroke="#385d91" stroke-width="4"/><polyline points="'+curve(hb)+'" fill="none" stroke="#168b83" stroke-width="4"/><path d="M'+X(p)+' 65 V320" stroke="#c46c42" stroke-width="2" stroke-dasharray="6 5"/><circle cx="'+X(p)+'" cy="'+Y(mb(p))+'" r="6" fill="#385d91"/><circle cx="'+X(p)+'" cy="'+Y(hb(p))+'" r="6" fill="#168b83"/><text x="75" y="31" font-size="21">'+(zh?'占据比例 / %':'Occupied sites / %')+'</text><text x="355" y="31" font-size="20" fill="#385d91">Mb</text><text x="440" y="31" font-size="20" fill="#168b83">Hb</text><text x="310" y="393" text-anchor="middle" font-size="21">'+(zh?'氧分压 / mmHg':'Oxygen partial pressure / mmHg')+'</text></g>';const a=100*mb(p),b=100*hb(p),drop=100*(hb(100)-hb(p));get('result').textContent=zh?'在'+p+' mmHg，Mb占据约'+a.toFixed(2)+'%，Hb占据约'+b.toFixed(2)+'%。Hb从100 mmHg的环境变到当前条件，模型中的占据减少'+drop.toFixed(2)+'个百分点。提高P₅₀会把绿线向右移动，使同一分压下的占据降低。':'At '+p+' mmHg, Mb occupancy is about '+a.toFixed(2)+'% and Hb occupancy about '+b.toFixed(2)+'%. Moving Hb from 100 mmHg to the selected condition reduces model occupancy by '+drop.toFixed(2)+' percentage points. Increasing P₅₀ shifts the green curve right and lowers occupancy at the same pressure.';}pEl.addEventListener('input',update);hEl.addEventListener('input',update);get('reset').addEventListener('click',()=>{pEl.value=40;hEl.value=26;update();});update();});